# Task 1.7. N-bit adder
# Goal: Scalable ripple carry adder for N bits

from qiskit import QuantumCircuit

def arbitrary_adder(qc: QuantumCircuit, a: list, b: list, sum_qubits: list, carry: int) -> QuantumCircuit:
    # sum and carry start in |0>; compute sum = a + b, carry = final carry
    for i in range(len(b)):
        qc.cx(b[i], sum_qubits[i])
    _add_in_place(qc, a, sum_qubits, carry)
    return qc


def _mcx(qc, controls, target):
    controls = list(controls)
    if len(controls) == 0:
        qc.x(target)
    elif len(controls) == 1:
        qc.cx(controls[0], target)
    elif len(controls) == 2:
        qc.ccx(controls[0], controls[1], target)
    else:
        qc.mcx(controls, target)


def _mcx_pattern(qc, controls, target, pattern):
    zeros = [c for c, b in zip(controls, pattern) if not b]
    for c in zeros:
        qc.x(c)
    _mcx(qc, controls, target)
    for c in zeros:
        qc.x(c)


def _mcz(qc, qubits):
    qubits = list(qubits)
    if len(qubits) == 0:
        qc.global_phase += 3.141592653589793
    elif len(qubits) == 1:
        qc.z(qubits[0])
    elif len(qubits) == 2:
        qc.cz(qubits[0], qubits[1])
    else:
        qc.h(qubits[-1])
        qc.mcx(qubits[:-1], qubits[-1])
        qc.h(qubits[-1])


def _increment(qc, reg, ctrls):
    # reg is little-endian; add 1 mod 2^len(reg), controlled on ctrls
    reg = list(reg)
    for k in reversed(range(len(reg))):
        _mcx(qc, list(ctrls) + reg[:k], reg[k])


def _decrement(qc, reg, ctrls):
    reg = list(reg)
    for k in range(len(reg)):
        _mcx(qc, list(ctrls) + reg[:k], reg[k])


def _add_in_place(qc, a, b, carry=None):
    # b <- b + a ; if carry given, it is the top bit of the target register
    a = list(a); b = list(b)
    for i in range(len(a)):
        reg = b[i:] + ([carry] if carry is not None else [])
        _increment(qc, reg, [a[i]])


def _sub_in_place(qc, a, b, borrow=None):
    a = list(a); b = list(b)
    for i in reversed(range(len(a))):
        reg = b[i:] + ([borrow] if borrow is not None else [])
        _decrement(qc, reg, [a[i]])

