    for qa, qb in zip(reg_a, reg_b):
        qc.cx(qa, qb)
    _mcx_pattern(qc, list(reg_b), target, [False] * len(reg_b))
    for qa, qb in zip(reg_a, reg_b):
        qc.cx(qa, qb)
    return qc


