    Returns:
        Modified quantum circuit
    """
    zeros = [q for q, b in zip(query, pattern) if not b]
    for q in zeros:
        qc.x(q)
    _mcz(qc, query)
    for q in zeros:
        qc.x(q)
    return qc


def _mcx(qc, controls, target):
    controls = list(controls)
    if len(controls) == 0:
        qc.x(target)
    elif len(controls) == 1:
        qc.cx(controls[0], target)
    elif len(controls) == 2:
        qc.ccx(controls[0], controls[1], target)
    else:
        qc.mcx(controls, target)


def _mcx_pattern(qc, controls, target, pattern):
    zeros = [c for c, b in zip(controls, pattern) if not b]
    for c in zeros:
        qc.x(c)
    _mcx(qc, controls, target)
    for c in zeros:
        qc.x(c)


def _mcz(qc, qubits):
    qubits = list(qubits)
    if len(qubits) == 0:
        qc.global_phase += 3.141592653589793
    elif len(qubits) == 1:
        qc.z(qubits[0])
    elif len(qubits) == 2:
        qc.cz(qubits[0], qubits[1])
    else:
        qc.h(qubits[-1])
        qc.mcx(qubits[:-1], qubits[-1])
        qc.h(qubits[-1])
